\end{cases}
\]If the graph of $y=f(x)$ is continuous (which means the graph can be drawn without lifting your pencil from the paper), and $f(2) = 1$, what is the value of $a + b?$

[asy]
size(150);
real bound = 5;
int x, y;
for (x = -1; x <= bound; ++x) {
  for (y = -1; y <= bound; ++y) {
    dot((x,y));
  }
}
real g(real x) {return 2*x - 3;}
draw(graph(g,-1,5), red);
for(int i = 0; i < 4; ++i) {
  draw((-0.4,y+.0001)--(-0,0)--(-0,y),EndArrow);
